const featured=[{section:'stop',name:'Stoptavle og fuldt stop',title:'Stoptavle og fuldt stop',tag:'VIGEPLIGT',description:'Stop helt op, før du kører videre.',art:'stop',color:'var(--pink)'},{section:'sving-cykel',name:'Højresving og cyklister',title:'HØJRESVING OG CYKLISTER',tag:'CYKLISTER',description:'Du har blinket. Cyklisten kører stadig ligeud.',art:'bike',color:'var(--cyan)'},{section:'ubetinget',name:'Ubetinget vigepligt ved hajtænder',title:'UBETINGET VIGEPLIGT VED HAJTÆNDER',tag:'KRYDS',description:'Din bil er ikke hovedpersonen i alle kryds.',art:'yield',color:'var(--acid)'}];
