function currentQuestion(){return session?.questions[session.index];}
function questionNarrationCue(){const panel=document.querySelector('#view .question-panel');return createVoiceCue([panel?.querySelector('.question-context'),...[...(panel?.querySelectorAll('.statement')||[])].flatMap(row=>[row,row])]);}
function shownOrder(q,examMode=location.hash==='#exam'&&!!exam){return statementOrder(examMode?`${exam.id}:${q.id}`:`${session.accessId||=freshTabId()}:${session.phase}:${q.id}`);}
