function questionBlock(q,answers,{checked=false,examMode=false}={}){return `<div class="question-panel"><div class="eyebrow">${examMode?'ØVEPRØVE / EGEN BEDØMMELSE':session?.phase==='recall'?'HVAD HUSKER DU? / UDEN FACIT':'SE SITUATIONEN. TAG STILLING.'}</div><h2>${esc(q.prompt)}</h2><p class="question-context">${esc(q.context)}</p><button class="audio-btn voice-read" data-action="read" type="button" aria-pressed="false">${icon('speaker')} Læs situationen op</button><div class="answer-note">VURDÉR ALLE 4 UDSAGN. FLERE KAN VÆRE RIGTIGE.</div>${examMode?'<p class="exam-selection-note">Her ser du dit valg. Facit kommer, når du har afleveret.</p>':''}<div class="statements">${shownOrder(q,examMode).map((i,shown)=>{const s=q.statements[i];return `<div class="statement ${checked?(answers[i]===s.correct?'correct':'incorrect'):''}"><span class="statement-index">${shown+1}</span><span class="statement-text">${esc(s.text)}</span><div class="yes-no" role="group" aria-label="Udsagn ${shown+1}: ${esc(s.text)}"><button class="choice-btn ${answers[i]===true?'selected':''}" data-choice="${i}" data-value="true" aria-pressed="${answers[i]===true}" aria-label="Udsagn ${shown+1}, ja" ${checked?'disabled':''}>JA</button><button class="choice-btn ${answers[i]===false?'selected':''}" data-choice="${i}" data-value="false" aria-pressed="${answers[i]===false}" aria-label="Udsagn ${shown+1}, nej" ${checked?'disabled':''}>NEJ</button></div>${checked?`<span class="verdict-dot" aria-label="${answers[i]===s.correct?'Korrekt':'Forkert'}">${answers[i]===s.correct?ico('check'):ico('x')}</span>`:''}</div>`;}).join('')}</div>${checked?feedback(q,gradeQuestion(q,answers)):''}<div class="question-actions">${examMode?`<button class="btn btn-secondary" data-action="exam-prev" ${exam.index===0?'disabled':''}>${icon('back')} Tilbage</button><button class="btn btn-primary" data-action="exam-next">${exam.index===24?'Se oversigt og aflever':'Næste situation'} ${icon('arrow')}</button>`:checked?`<span class="small">DU KAN ALTID PRØVE IGEN</span><button class="btn btn-primary" data-action="mission-next">${session.phase==='recall'?'Se dit resultat':'Fortsæt'} ${icon('arrow')}</button>`:`<span class="small" id="answer-count">${answers.filter(a=>a!==null).length}/4 VURDERET</span><button class="btn btn-primary" data-action="check" ${answers.some(a=>a===null)?(session?.phase==='recall'?'disabled':'disabled data-auto'):''}>Tjek mit svar ${icon('arrow')}</button>`}</div></div>`;}
function pictureHeldBack(q){const held=session.heldPictures||={};held[q.id]??=!!readSeen()[q.id];return held[q.id]&&!session.checked;}
function heldScene(){return `<section class="scene-panel scene-held" aria-label="Billedet vises efter dit svar"><p>Du har set situationen før. Billedet kommer, når du har svaret. Vurder ud fra teksten.</p></section>`;}
