function missionView(){if(!session||!currentQuestion())return home();const q=currentQuestion();return `<div class="screen-head"><a class="back-btn" href="#missions" aria-label="Tilbage til øvelser">${icon('back')}</a><div><div class="eyebrow">${session.phase==='recall'?'ØV REGLEN IGEN':'KORT ØVELSE'}</div><h1>${session.phase==='recall'?'Sidder den fast?':esc(sectionMap.get(q.sectionId)?.title||'Din næste øvelse')}</h1></div><div class="mission-info">${session.phase==='recall'?'HVAD HUSKER DU?':`${session.index+1} / ${session.questions.length}`}</div></div><div class="journey-progress mission-progress" role="progressbar" aria-label="Fremgang i øvelsen" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(100*(session.phase==='recall'?session.questions.length:session.index)/(session.questions.length+1))}"><i style="--journey-progress-ratio:${Math.max(.06,((session.phase==='recall'?session.questions.length:session.index)+.5)/(session.questions.length+1)).toFixed(3)}">${progressCar()}</i></div>${session.phase!=='recall'&&session.questions.length>1?'<p class="mission-mix-note">Din valgte regel og 2 andre emner. Til sidst prøver du at huske en af dem.</p>':''}${session.phase==='recall'?`<div class="recall-banner">Et nyt spørgsmål fra samme emne. Tænk på reglen, før du svarer.</div>`:''}<div class="question-layout">${pictureHeldBack(q)?heldScene():sceneBlock(q)}${questionBlock(q,session.answers,{checked:session.checked})}</div>`;}
function feedback(q,correct){const gag=esc(q.gag),showGag=state.settings.humor && questionGagFits(q,correct);return `<div class="feedback ${correct?'':'wrong'}" role="status">${showGag ? `<div class="feedback-cast">${renderCast(q.speaker,{size:'sm',mood:correct?'correct':'wrong'})}</div>` : ''}<h3 class="fb-head"><span class="fb-badge" data-rive="feedback:${correct?'right':'wrong'}">${ico(correct?'check':'x')}</span>${correct?'Godt kørt! Det er rigtigt.':'Ikke helt. Læs reglen igen, så ved du det næste gang.'}</h3><p>${esc(q.explanation)}</p>${badges(q.sourceIds)}<button class="audio-btn voice-read" type="button" data-voice-kind="question-feedback" data-voice-id="${esc(q.id)}" data-voice-correct="${correct}" aria-pressed="false">Lyt til forklaringen</button>${showGag ? `<div class="gag"><div><p>${gag}</p></div></div>` : ''}</div>`;}
function updateQuestion(){/* BILLING HOOK */const accessAttempt=(session.accessId||=freshTabId())+':'+session.phase+':'+session.index;if(!premium.practiceAllowed(accessAttempt))return;questionVisual?.dispose();questionVisual=null;world?.dispose();world=null;$('view').innerHTML=missionView();applySettings();bindPage('mission','');}
function checkMission(){if(session.checked||session.answers.some(a=>a===null))return;/* BILLING HOOK: one quota entry per answered practice attempt. */const accessAttempt=(session.accessId||=freshTabId())+':'+session.phase+':'+session.index;if(!premium.practiceAllowed(accessAttempt))return;premium.recordPractice(accessAttempt);const q=currentQuestion(),before=state.xp,result=recordAnswer(state,q,session.answers);markSeen(q.id);session.checked=true;session.results.push({question:q.id,correct:result.correct,recall:session.phase==='recall'});save();/* a wrong statement already played its sound when it was answered */if(result.correct||session.phase==='recall')sound(result.correct);updateQuestion();const f=document.querySelector('.feedback');if(f){f.setAttribute('tabindex','-1');f.focus({preventScroll:true});f.scrollIntoView({behavior:state.settings.motion&&!reduceMotion.matches?'smooth':'instant',block:'nearest'});}}
function nextMission(){if(!session.checked)return;if(session.phase==='recall'){state.sessions++;save();location.hash='result';return;}if(session.index<session.questions.length-1){session.index++;}else{const failed=session.results.find(r=>!r.correct),pick=session.questions.find(q=>q.id===failed?.question)||session.questions[0],seen=readSeen(),asked=new Set(session.results.map(r=>r.question)),pool=QUESTIONS.filter(q=>q.sectionId===pick.sectionId&&!asked.has(q.id)),variant=(pick.sectionId==='stop'?pool.find(q=>!seen[q.id]&&/mur|skjult/i.test(q.context)):null)||pickFresh(pool,seen);if(!variant){state.sessions++;save();location.hash='result';return;}session.questions=[variant];session.index=0;session.phase='recall';}session.answers=[null,null,null,null];session.checked=false;updateQuestion();window.scrollTo({top:0,behavior:'instant'});}
function missionResult(){if(!session)return home();const clean=session.results.filter(r=>r.correct).length,n=session.results.length;return `<section class="result-hero"><div class="result-art art-scene">${renderCast('kegle',{size:'md',mood:clean===n?'correct':'wrong'})}</div><div class="result-mark art-result-symbol">${clean===n?'W':'ØV'}</div><div class="eyebrow" style="justify-content:center">ØVELSE GENNEMFØRT</div><h1>${clean===n?'REGLERNE BEGYNDER AT SIDDE.':'GOD ØVNING. TAG REGLEN MED.'}</h1><p>${clean===n?'Du har taget stilling, forstået forklaringerne og husket en regel. Gentag den senere, så den sidder bedre fast.':'Nu ved vi, hvad du skal øve. Øv dem igen nu, eller prøv et andet emne.'}</p><div class="result-stats"><div><strong>${clean}/${n}</strong><span>KORREKTE SITUATIONER</span></div><div><strong>${state.sessions}</strong><span>ØVELSER</span></div></div><div class="result-actions"><a href="#review" class="btn btn-primary">Øv dem igen ${icon('route')}</a><a href="#missions" class="btn btn-secondary">Vælg en ny øvelse ${icon('arrow')}</a></div></section><div class="result-list">${session.results.map(r=>{const q=QUESTIONS.find(q=>q.id===r.question),s=sectionMap.get(q?.sectionId);return `<div class="result-row"><span class="result-indicator ${r.correct?'':'wrong'}">${r.correct?ico('check'):ico('repeat')}</span><div><h3>${esc(s?.title)} ${r.recall?'<span class="mono">/ HVAD HUSKER DU?</span>':''}</h3><p>${r.correct?'Rigtigt denne gang. Reglen kommer tilbage senere.':'Denne regel er først på listen, når du øver igen.'}</p></div><a class="btn btn-secondary" href="#chapter:${s?.chapter.id}">Se reglen</a></div>`}).join('')}</div>${footer()}`;}
