// The start page's glow-up machine as Rive (the Hero artboard, one vehicle per file, swapped when it has driven off).
// The CSS machine runs instead when motion is off or Rive fails. Returns a dispose function.
function mountHero(gu,opts){
  if(document.body.classList.contains('no-motion')||reduceMotion.matches)return mountGlowUp(gu,opts);
  const stage=gu.querySelector('.gu-stage'),bases=(gu.dataset.glowup||'scooter').split(','),loop=gu.dataset.loop==='1';
  const from=gu.querySelector('.gu-from'),to=gu.querySelector('.gu-to');
  let i=0,timers=[],stop=null,dead=false;
  const clear=()=>{timers.forEach(clearTimeout);timers=[];};
  const show=b=>{gu.dataset.active=b;if(from){from.textContent=DREAMS[b].from;to.textContent=DREAMS[b].to;}gu.setAttribute('aria-label',`${DREAMS[b].from} bliver til ${DREAMS[b].to}, del for del`);riveSwap(stage,'hero:'+b);};
  const onOn=()=>{if(dead)return;clear();const b=bases[i],next=bases[(i+1)%bases.length];if(bases.length>1)rivePreload('hero:'+next);
    timers=dreamCues(b).map(([ms,cue])=>setTimeout(()=>opts.sound?.(cue),ms));
    timers.push(setTimeout(()=>{if(!loop&&i===bases.length-1){opts.onDone?.();return;}i=(i+1)%bases.length;show(bases[i]);},7250));}; // 7250: the Hero show's length (tools/rive/build-glowup.mjs)
  const onOff=()=>{if(dead||stop)return;clear();stage.removeEventListener('rive-on',onOn);stage.removeAttribute('data-rive');stage.removeAttribute('data-rive-on');stop=mountGlowUp(gu,opts);};
  stage.addEventListener('rive-on',onOn);stage.addEventListener('rive-off',onOff,{once:true});
  gu.dataset.active=bases[0];stage.dataset.rive='hero:'+bases[0];
  return()=>{dead=true;clear();stage.removeEventListener('rive-on',onOn);stop?.();};
}
function startPlan(){const vm=journeyViewModel('');const next=vm.recommendations?.recommended||vm.recommendations?.next||vm.units.flatMap(u=>u.nodes||[])[0];return {firstTitle:next?.title||'Dit første regelkort',firstHref:next?'#journey:'+next.sectionId:'#home'};}
